INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770275822402, 'Alpine Status', 'HDZ-W10', '10" Subwoofer', '장착공임 별도', 1300000, 'assets/images/AST-w10.jpg', '[{"id":1770275805850.4597,"type":"text","value":"Pulp-Mica Cone Body\nCarbon Fiber Dust Cap\nCast Aluminum Frame\nTriple Stacked High-Power Strontium Ferrite Magnets (174oz x 3)\nDual Progressive Spiders with Integrated Tinsel Leads\nHigh-Amplitude Multi-Roll (H.A.M.R.) Surround\nIncluded Mesh Grille with Aluminum Trim Ring\nMounting Depth: 7-7/16\"\nX-Max: 20mm · Voice Coil: 65mm\nFrequency Response: 26Hz-200Hz\nSensitivity: 82.2dB\nNominal Impedance: 4Ω+4Ω\nPower Handling: 800W RMS / 2400W Peak"},{"id":1770275946176.2114,"type":"image","value":"assets/images/AST-w10-01.jpg"}]'::jsonb, '[{"id":1770278312810,"name":"OM_HDZ-W10_HDZ-W12","url":"assets/files/OM_HDZ-W10_HDZ-W12.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770276139112, 'Alpine Status', 'HDA-F60', 'Hi-Res Audio 4CH Amplifier', '장착공임 별도', 1800000, 'assets/images/AST-F60.jpg', '[{"id":1770276169594.5251,"type":"text","value":"100Wx4ch (4Ω)\n150Wx4ch (2Ω)\nBridged 300Wx2ch (4Ω)\nTHD+N ≤0.02% (10W), ≤0.07% (Rated Power)\nS/N Ratio >106dB\nFrequency Response (-3dB) 10-60kHz (Hi-Res)\nDamping Factor >500\nSize (mm) W297xD192xH50.8"},{"id":1770276233868.644,"type":"text","value":"Alpine 3세대 Ultra High-resolution Alpine F#1Status 시스템에서 도출된 동일한 엔지니어링 및 디자인 컨셉을 사용하여 Alpine은 보다 쉽고 접근성이 뛰어난 가격대의 고해상도 사운드를 구현하기 위해 **\"Alpine Status\"**를 개발했습니다.\n\nAlpine Status 시스템은 또한 매우 유연합니다. 모든 구성 요소를 구입하여 \"독립형\" 구성에 사용할 수 있습니다.\n\nHDA-F60 Hi-Res Audio 인증 4채널 앰프는 사운드 성능에서 업계 벤치마크를 재정의하여 진정한 고해상도 사운드 재생을 제공합니다.\n\nAll-New 디지털 디자인은 엄청난 양의 전력 출력과 이러한 앰프를 모든 면에서 최고 수준으로 만드는 놀라운 **감쇠 계수(Damping Factor)**를 제공합니다.\n\n최고 수준의 성능을 갖춘 HDA-F60은 10-60kHz의 주파수 응답과 500 이상의 감쇠 계수를 통해 높은 전력 출력을 정밀하게 제공할 뿐만 아니라 최상의 고화질 사운드 경험을 제공합니다."},{"id":1770276285332.866,"type":"image","value":"assets/images/AST-F60-01.jpg"},{"id":1770276355868.2068,"type":"image","value":"assets/images/AST-F60-02.jpg"}]'::jsonb, '[{"id":1770278393868,"name":"OM_HDA-M80_HDA-F60_HDA-V90","url":"assets/files/OM_HDA-M80_HDA-F60_HDA-V90.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770276535208, 'DSP/AMP', 'PXE-M60-4', '4CH DSP Amplifier', '장착 공임 별도/20만원 부터', 750000, 'assets/images/DSP-M60.jpg', '[{"id":1770276589023.5386,"type":"text","value":"Inputs\n4 Ch Hi-Level / 2-Ch RCA\nHD Bluetooth\n[Hi-Level Input 28Vpp]\n\nOutputs\n4 Ch Hi-Level / 2 Ch RCA\n4CH x 50W max\n\nSampling Rate : 48kHz/24Bit"},{"id":1770276740018.9731,"type":"image","value":"assets/images/DSP-M60-01.jpg"},{"id":1771483413733.8022,"type":"text","value":"알파인(Alpine)의 PXE-M60-4는 합리적인 가격대에 강력한 사운드 프로세싱 성능을 갖춘 4채널 앰프 일체형 DSP입니다. 이 모델이 동급 제품들 사이에서 돋보이는 제품 입니다.\n\n1. 뛰어난 가성비와 입문자 친화성\n가장 큰 장점은 ''알파인(Alpine)''이라는 브랜드 신뢰도 대비 가격이 매우 합리적이라는 점입니다. 고가의 하이엔드 DSP로 가기에는 부담스럽고, 저가형 중국산 브랜드의 안정성이 우려되는 사용자들에게 가장 완벽한 대안입니다.\n\n2. ''내비 믹스(Navi Mix)'' 기능\n순정 헤드유닛을 그대로 사용하는 환경에서 특히 빛을 발합니다. 음악 감상 중에 순정 내비게이션 안내 음성이 나오면 자연스럽게 섞여 출력되도록 설계되어, 안내음을 놓치거나 음악이 툭 끊기는 불편함이 없습니다.\n\n3. 초소형 사이즈와 고효율\n가로 160mm, 세로 140mm의 콤팩트한 크기 덕분에 시트 아래나 대시보드 안쪽 등 좁은 공간에도 장착이 용이합니다. 또한, 저전력 고효율 설계로 차량 배터리에 무리를 주지 않으면서도 순정 대비 훨씬 선명한 해상력을 제공합니다.\n\n4. PXE-M60-4는 다음과 같은 상황에서 최고의 효율을 발휘합니다.\n\n1)순정 헤드유닛을 유지해야 하는 차량: 최신 국산차(현대/기아)나 수입차처럼 인포테인먼트 시스템이 일체형이라 데크 교체가 불가능한 경우.\n\n2)자출(내장 앰프) 사양 차량: 별도의 외장 앰프가 없는 기본 오디오 옵션 차량에서 사운드 스테이지(무대감)를 만들고 싶을 때 강력 추천합니다.\n\n3)공간 제약이 큰 소형/준중형 차량: 트렁크 공간을 차지하지 않고 깔끔한 매립형 튜닝을 선호하는 차주분들께 적합합니다.\n\n4)추천 차종 예시\n  - 국산차: 아반떼(CN7), 셀토스, 코나, 스포티지, 쏘렌토(기본 오디오), 트레일블레이저 등\n  - 수입차: BMW 1/3시리즈(기본 오디오), 미니 쿠퍼, 폭스바겐 골프 등\n\n\"순정 스피커의 답답함을 해소하고 싶지만, 대공사는 부담스러운\" 유저들에게 최고의 선택지입니다. 만약 4채널 출력을 넘어 더 강력한 베이스를 원하신다면, 남는 2채널 RCA 출력을 이용해 액티브 서브우퍼(PWE-M770)를 추가로 연결하는 구성도 가능합니다."},{"id":1771483949540.1335,"type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/PXE-M60-4-001.jpg"}]'::jsonb, '[{"id":1770278425830,"name":"PXE-M60-4","url":"assets/files/PXE-M60-4.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770278648001, 'DSP/AMP', 'PXE-R80-8', '8CH DSP Amplifier', '장착 공임 별도/20만원 부터', 1100000, 'assets/images/DSP-R80.jpg', '[{"id":1770279257214.2046,"type":"text","value":"Inputs\n6 Ch Hi-Level / 2-Ch RCA\nHD Bluetooth\n[Hi-Level Input 28Vpp]\n\nOutputs\n8 Ch Hi-Level / 8 Ch RCA\n8CH x 70W MAX\nSampling Rate : 48kHz/24Bit\n\nSound & Tuning\n31-Band Parametric or Graphic EQ\nHPF / LPF / Bandpass Crossover per channel\nSoftware PC\nMatrix input summing"},{"id":1770279339607.9854,"type":"image","value":"assets/images/DSP-R80-01.jpg"},{"id":1771484234776.5977,"type":"text","value":"알파인의 PXE-R80-8은 하이엔드급 8채널 앰프 일체형 DSP입니다.\n\n1. 8채널 출력\nR80-8은 **8채널의 강력한 출력(정격 50W x 8)**을 내장하고 있습니다.\n특히 8채널 RCA 출력을 지원하여, 내장 앰프로 프런트와 리어 스피커를 밀어주면서도 별도의 고출력 외장 앰프를 추가해 서브우퍼나 미드레인지 등을 정교하게 제어할 수 있습니다.\n\n2. 정교한 3-Way 액티브 시스템 구축 가능\n프런트 스피커를 트위터, 미드레인지, 미드우퍼로 나누어 각각 제어하는 **''3-Way 액티브 시스템''**을 단 한 대의 기기로 완벽하게 구현할 수 있습니다. 각 채널마다 독립적인 31밴드 EQ와 타임 얼라이먼트 설정이 가능해, 운전석 중심의 정밀한 사운드 스테이지를 만드는 데 최적화되어 있습니다.\n\n3. PXE-R80-8은 시스템의 복잡도가 높고 고음질을 지향하는 환경에 적합합니다.\n\n - 순정 외장 앰프가 장착된 차량: 앰프에서 각 스피커로 신호가 쪼개져 나가는 고급 오디오 옵션(예: KRELL, 보스, 하만카돈 등) 차량의 신호를 하나로 합쳐(Summing) 재구성할 때 탁월합니다.\n\n - 본격적인 오디오 튜닝을 원하는 환경: 단순 스피커 교체를 넘어, 차량 내부의 소리 반사각까지 고려한 정밀 세팅이 필요한 경우입니다.\n\n - 대형 SUV 및 다채널 스피커 차량: 스피커 개수가 많은 대형 차량에서도 채널 부족 걱정 없이 모든 유닛을 독립적으로 제어할 수 있습니다.\n\n4. 이런 차에 적합합니다.\n\n - 국산 SUV/세단: KGM 토레스/액티언(Q300 등), 현대 팰리세이드, 기아 카니발/EV9 등 스피커 개수가 많고 공간이 넓은 차량.\n\n - 수입 프리미엄 브랜드: 벤츠 E클래스(W213 이상), BMW 5시리즈(G30계열) 등 순정 시스템과의 연동이 복잡한 차종."},{"id":1771486032423.046,"type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/PXE-R80-8-001.jpg"}]'::jsonb, '[{"id":1770278645216,"name":"PXE-R80-8 Owners manual","url":"assets/files/PXE-R80-8 Owners manual.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770279659907, 'DSP/AMP', 'PXE-R100-8', '8CH DSP Amplifier', '장착 공임 별도/20만원 부터', 1300000, 'assets/images/DSP-R100.jpg', '[{"id":1770279625267.0005,"type":"text","value":"Inputs\n6 Ch Hi-Level / 2-Ch RCA\nHD Bluetooth / Optical / Coaxial\n[Hi-Level Input 28Vpp]\n\nOutputs\n8 Ch Hi-Level / 10 Ch RCA\n8CH x 70W MAX\nSampling Rate : 96kHz/24Bit\n\nSound & Tuning\n31-Band Parametric or Graphic EQ\nHPF / LPF / Bandpass Crossover per channel\nSoftware PC\nMatrix input summing"},{"id":1770279718849.2869,"type":"image","value":"assets/images/DSP-R100-01.jpg"},{"id":1771486226997.1343,"type":"text","value":"알파인(Alpine)의 PXE-R100-8은 하이엔드 오디오 시스템의 정점을 찍기 위해 설계된 8채널 앰프 일체형 DSP입니다.\n\nR100-8은 더 강력한 출력과 압도적인 신호 처리 능력으로 무장한 모델입니다.\n\n1. 고출력 파워 앰프의 안정성 (8채널 x 50W RMS)\n단순히 소리를 키우는 것이 아니라, 고음역대의 미세한 떨림부터 저음역대의 묵직한 타격감까지 **댐핑 능력(스피커를 제어하는 힘)**이 정교합니다.\n\n2.12채널의 정밀한 프로세싱 & 확장성\n총 12채널의 독립적인 프로세싱이 가능하여, 8채널은 내장 앰프로 구동하고 나머지 4채널은 RCA 출력을 통해 고성능 외장 앰프나 서브우퍼 전용 앰프로 연결할 수 있습니다.\n\n3-Way 프런트 + 리어 + 서브우퍼라는 완벽한 풀 시스템을 구축할 때 가장 이상적인 허브 역할을 합니다.\n\n3. 하이엔드 전용 부품 채용 (Audiophile Grade)\n내부 커패시터와 OP-AMP 등 핵심 소자들이 음질 지향적인 하이엔드 등급으로 업그레이드되어 있습니다. 노이즈 억제력이 탁월하며, 대음량에서도 소리가 뭉개지지 않는 ''하이파이(Hi-Fi)'' 본연의 해상력을 선사합니다.\n\n4. 통합 마스터 컨트롤 및 고해상도 지원\nR100-8은 고해상도 오디오 인증을 받았을 뿐만 아니라, 동축(Coaxial) 및 광(Optical) 입력을 모두 지원하여 디지털 소스 기기와의 직결 시 손실 없는 원음 재생이 가능합니다.\n\n5. PXE-R100-8은 차량의 오디오 시스템이 매우 복잡하거나, 소리 하나하나의 질감에 집중하는 환경에 강력히 추천합니다.\n\n - 순정 프리미엄 오디오 옵션 완벽 대응: 앰프 신호가 다채널로 분리된 최고급 오디오 옵션(예: 제네시스 렉시콘, 벤츠 부메스터, BMW 바워스 앤 윌킨스 등) 차량에서 순정 기능을 유지하며 음질만 극대화하고 싶을 때.\n\n - 본격적인 ''풀 멀티'' 시스템 구축: 트위터, 미드레인지, 미드우퍼를 각각 독립적으로 정밀 제어하고자 하는 하이엔드 지향 시스템.\n\n - 노이즈에 민감한 전기차(EV): 전기차 특유의 정숙한 실내 환경에서 느껴지는 미세한 화이트 노이즈를 최소화하고 선명한 사운드를 즐기고 싶은 경우.\n\n6. 추천 차종 예시\n\n - 프리미엄 세단 및 SUV: 제네시스 GV80/G80, 벤츠 S클래스/GLE, BMW X5/X7, 아우디 A8/Q8 등.\n\n - 신규 플랫폼 차량: KGM 액티언(Q300), 토레스 등 최신 인포테인먼트가 적용되어 정밀한 신호 보정(Summing/EQ)이 필수적인 차량."},{"id":1771486432143.9194,"type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/PXE-R80-8-001.jpg"}]'::jsonb, '[{"id":1770280031407,"name":"PXE-R100-8 Owners manual","url":"assets/files/PXE-R100-8 Owners manual.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770279980374, 'DSP/AMP', 'PXE-X120-8', '8CH DSP Amplifier', '장착 공임 별도/20만원 부터', 1600000, 'assets/images/DSP-X120-8.jpg', '[{"id":1770280098161.475,"type":"text","value":"Inputs\n12 Ch Hi-Level / 2-Ch RCA\nHD Bluetooth / Optical / Coaxial\n[Hi-Level Input 30Vpp]\n\nOutputs\n8 Ch Hi-Level / 12 Ch RCA\n1CH~4CH x 100W max + 5CH~8CH x 50W max\nSampling Rate : 96kHz/24Bit\n\nSound & Tuning\n31-Band Parametric or Graphic EQ\nHPF / LPF / Bandpass Crossover per channel\n\nSoftware PC\nMatrix input summing"},{"id":1770280340336.0093,"type":"image","value":"assets/images/DSP-X120-8-01.jpg"},{"id":1771486799332.9878,"type":"text","value":"알파인의 PXE-X120-8은 알파인 DSP 라인업 중에서도 **''플래그십(Flagship)''**의 등급을 담당하는 고성능 모델입니다.\n\n1. 초정밀 하이엔드 오디오 프로세싱 (64-bit DSP)\n32-bit 프로세싱을 사용한다면, X120-8은 64-bit 더블 프리시전(Double Precision) 부동 소수점 DSP 칩을 탑재하여 연산 속도와 정밀도가 비약적으로 향상되었습니다.\n\n이는 소리의 왜곡(Distortion)을 극한으로 줄이고, 아주 미세한 배음(Harmonics)까지 재생하여 훨씬 더 입체적이고 사실적인 사운드 스테이지를 구현합니다.\n\n2. 압도적인 신호 대 잡음비 (S/N Ratio 110dB 이상)\n하이엔드 소스 유닛에 버금가는 110dB 이상의 S/N비를 자랑합니다.\n\n엔진 소음이 적은 전기차나 정숙한 대형 세단에서 음악의 휴지기(Silence) 동안 들리는 미세한 ''화이트 노이즈''를 완벽에 가깝게 억제하여, 극강의 투명한 음질을 제공합니다.\n\n3. 강력하고 안정적인 전원부 설계\nX120-8은 8채널 정격 출력을 지원하면서도, 전원부 회로에 대용량 고품질 커패시터를 대거 채용했습니다.\n\n급격한 출력이 필요한 저음역대의 비트나 오케스트라의 총주 시에도 전압 강하 없이 안정적으로 스피커를 드라이빙하여, 소리의 밀도감이 좋습니다.\n\n4. 지능형 매트릭스 믹싱 (Advanced Matrix Mixing)\n순정 오디오 시스템의 신호가 트위터/미드/우퍼로 복잡하게 쪼개져 있는 경우, 이를 완벽하게 하나의 신호로 합치거나(Summing) 사용자가 원하는 대로 자유롭게 분배하는 능력이 매우 뛰어납니다. 복잡한 시스템에서도 위상 간섭 없는 완벽한 보정이 가능합니다.\n\n5. PXE-X120-8은 단순한 ''소리 개선''을 넘어, ''차 안을 청음실로 바꾸고 싶은'' 하이파이 유저들에게 추천합니다.\n\n - 순정 시스템이 극도로 복잡한 최신 수입차: 단순한 앰프 추가로는 해결되지 않는 정교한 신호 보정이 필요한 차량(예: 최신 BMW OS8 적용 차량, 벤츠 하이퍼스크린 탑재 차량 등).\n\n - 고성능 스피커 유닛과의 조합: 유토피아(Utopia), 소너스 파베르 등 초고가 스피커 유닛의 잠재력을 100% 끌어내고 싶은 환경.\n\n - 프로페셔널 튜너의 손길이 닿는 시스템: 장비의 성능이 워낙 뛰어나기 때문에, RTA(실시간 분석기) 장비를 활용한 정밀 튜닝이 수반되는 환경에서 그 가치가 증명됩니다.\n\n6. 추천 차종 예시\n\n - 플래그십 세단: 벤츠 S클래스(W223), BMW 7시리즈(G70), 제네시스 G90.\n\n - 고급 전기차: 테슬라 모델 S/X, 포르쉐 타이칸, 제네시스 GV60 등 전원의 안정성과 저노이즈가 생명인 차량.\n\n - KGM 프리미엄 라인: **액티언(Q300)**이나 렉스턴급 차량에서 순정 오디오 시스템의 한계를 완전히 뛰어넘고 싶을 때.\n\n"},{"id":1771486980288.1765,"type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/PXE-X120-8-001.jpg"}]'::jsonb, '[{"id":1771560045802,"name":"PXE-X120-8 Owners manual","url":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/files/PXE-X120-8%20Owners%20manual.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;